const sd = $getWorkflowStaticData('global');
sd.allClinics = [];
return [{ json: { page: 1 } }];
// ok

const resp = $input.first().json;
const contentHtml = resp.content || '';
const pagination = resp.pagination || {};
const currentPage = pagination.page || 1;
const maxPages = pagination.max_num_pages || 1;

const clean = (s) => s
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&#8211;/g, '-')
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .trim();

const getWidget = (cls) => [...contentHtml.matchAll(new RegExp('elementor-element-' + cls + '[^>]*>\\s*<div class="elementor-widget-container">\\s*([\\s\\S]*?)<\\/div>', 'g'))].map(m => clean(m[1]));

function normalizePhone(raw) {
  if (!raw) return '';
  // ambil nombor pertama sahaja (buang yang selepas '/' atau ';')
  const first = raw.split(/[\/|;,]/)[0];
  const m = first.match(/\+?\d[\d\s\-()]*\d/);
  let digits = (m ? m[0] : first).replace(/\D/g, '');
  if (!digits) return '';
  if (digits.startsWith('00')) digits = digits.slice(2);
  if (digits.startsWith('0')) digits = '60' + digits.slice(1);
  else if (!digits.startsWith('60')) digits = '60' + digits;
  return '+' + digits;
}

const names = [...contentHtml.matchAll(/<h1 class="elementor-heading-title elementor-size-default">([^<]*)<\/h1>/g)].map(m => m[1].trim());
const addresses = getWidget('1b19c37');
const emails = getWidget('cad19a6').map(t => {
  const m = t.match(/mailto:([^\s"']+)/);
  return m ? m[1] : t;
});
const phones = getWidget('0b91f24').map(normalizePhone);

const CANONICAL = { 'Wilayah Persekutuan Kuala Lumpur': 'Kuala Lumpur', 'W.P. Kuala Lumpur': 'Kuala Lumpur', 'Pulau Pinang': 'Penang' };
const STATE_KEYS = [
  ['WILAYAH PERSEKUTUAN KUALA LUMPUR', 'Kuala Lumpur'],
  ['W.P. KUALA LUMPUR', 'Kuala Lumpur'],
  ['KUALA LUMPUR', 'Kuala Lumpur'],
  ['PULAU PINANG', 'Penang'],
  ['PENANG', 'Penang'],
  ['NEGERI SEMBILAN', 'Negeri Sembilan'],
  ['JOHOR', 'Johor'],
  ['KEDAH', 'Kedah'],
  ['KELANTAN', 'Kelantan'],
  ['MELAKA', 'Melaka'],
  ['PAHANG', 'Pahang'],
  ['PERAK', 'Perak'],
  ['SELANGOR', 'Selangor'],
  ['TERENGGANU', 'Terengganu'],
  ['PUTRAJAYA', 'Putrajaya']
];

function detectState(address) {
  const a = address.toUpperCase();
  for (const [key, val] of STATE_KEYS) {
    if (a.includes(key)) return val;
  }
  // Fallback: state dikenali lewat poskod Malaysia
  const pc = address.match(/\b(\d{5})\b/);
  if (pc) {
    const pre = Number(pc[1].slice(0, 2));
    if (pre >= 40 && pre <= 48) return 'Selangor';
    if (pre >= 50 && pre <= 60) return 'Kuala Lumpur';
    if (pre === 62) return 'Putrajaya';
    if (pre >= 63 && pre <= 68) return 'Selangor';
    if (pre >= 70 && pre <= 73) return 'Negeri Sembilan';
    if (pre >= 75 && pre <= 78) return 'Melaka';
    if (pre >= 79 && pre <= 86) return 'Johor';
  }
  return 'UNKNOWN';
}

const results = [];
for (let i = 0; i < names.length; i++) {
  const address = addresses[i] || '';
  results.push({
    hcoName: names[i] || '',
    address,
    phone: phones[i] || '',
    email: emails[i] || '',
    state: detectState(address)
  });
}

// Kumpulkan ke accumulator global (belum ditulis ke sheet dulu)
const sd = $getWorkflowStaticData('global');
if (!sd.allClinics) sd.allClinics = [];
sd.allClinics.push(...results);

return [{ json: { currentPage, maxPages } }];

const first = $input.first().json;
const hasMore = first.currentPage < first.maxPages;
return [{ json: { page: first.currentPage + 1, hasMore } }];

const sd = $getWorkflowStaticData('global');
const all = sd.allClinics || [];
sd.allClinics = [];
// proses dari item terakhir: baris yang belum ada di sheet ditulis lebih dulu
return all.slice().reverse().map(c => ({ json: c }));
